import{_ as n,C as o,c as l,o as r,aa as s,G as a}from"./chunks/framework.Cn7WEiMX.js";const f=JSON.parse('{"title":"自定义方块定义","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/mod-support/custom-block-definitions.md","filePath":"wiki/Dynmap/mod-support/custom-block-definitions.md"}'),d={name:"wiki/Dynmap/mod-support/custom-block-definitions.md"};function c(p,e,m,u,_,h){const t=o("NolebaseGitContributors"),i=o("NolebaseGitChangelog");return r(),l("div",null,[e[0]||(e[0]=s('<h1 id="自定义方块定义" tabindex="-1">自定义方块定义 <a class="header-anchor" href="#自定义方块定义" aria-label="Permalink to &quot;自定义方块定义&quot;">​</a></h1> <p>Dynmap 支持通过数据驱动方法定义新方块，可以用于支持自定义方块类型，例如通过插件与客户端修改提供的方块。这些定义对 Dynmap 的射线追踪内部实现非常敏感，可能随未来版本的更新而改动或无效化，且不会提前告知——若有必要，尽力避免，请在大量投入之前理解我们的用意。</p> <h2 id="方块渲染的方式" tabindex="-1">方块渲染的方式 <a class="header-anchor" href="#方块渲染的方式" aria-label="Permalink to &quot;方块渲染的方式&quot;">​</a></h2> <p>在 Dynmap 中，方块渲染是通过一系列机制实现的，表现了 Minecraft 及其模组定义的不同类型方块。在所有情况中，渲染方块都包含两个核心元素：定义渲染方块的形状，以及用于在多种形状上添加颜色的纹理组。鉴于游戏本身由方块构成，大部分方块都只是简单的方形：因此，它们不需要自定义模型。</p> <p>对模组自定义方块的支持文件通过每个模组分别对应的两个文件实现：其一定义纹理映射（名称后接 <code>*-texture.txt</code>，放在 <code>renderdata</code> 目录（或其下的子目录）），其二定义非方块模型（名称后接 <code>*-models.txt</code>，同样放在 <code>renderdata</code> 目录或其子目录中）。对于只有方块的模组，不需要包含任何 <code>*-models.txt</code> 文件（因为对于任何没有模型的物体而言它们默认算作方块）。</p> <h2 id="创建纹理与模型定义文件" tabindex="-1">创建纹理与模型定义文件 <a class="header-anchor" href="#创建纹理与模型定义文件" aria-label="Permalink to &quot;创建纹理与模型定义文件&quot;">​</a></h2> <ul><li>对于纹理与模型定义文件，详见“纹理通用功能与模型定义文件”。</li> <li>对于纹理定义文件的格式详情，请见“纹理定义文件”。</li> <li>对于模型定义文件的格式详情，请见“模型定义文件”。</li></ul> <h2 id="定义方块" tabindex="-1">定义方块 <a class="header-anchor" href="#定义方块" aria-label="Permalink to &quot;定义方块&quot;">​</a></h2> <ul><li>定义简单的实心方块，请见“定义简单方块”章节。</li> <li>定义非一般方块的长方体模型，请见“定义立方体模型”章节。</li> <li>定义基于自定义方块渲染器的方块，请见“定义自定义渲染器方块”</li> <li>定义基于体积方块模型的方块，请见“定义体积模型方块”</li></ul> ',18)),a(t),a(i)])}const k=n(d,[["render",c]]);export{f as __pageData,k as default};
